args.CommandLine:
Get-ChildItem 'HKLM:\SYSTEM\CurrentControlSet\Enum\USB' | ForEach-Object {
  $vidpid = $_.PSChildName
  $subkeys = Get-ChildItem $_.PSPath -ErrorAction SilentlyContinue
  $first = $subkeys | Select-Object -First 1
  if ($first) {
    $p = Get-ItemProperty $first.PSPath -ErrorAction SilentlyContinue
    [PSCustomObject]@{
      VID_PID = $vidpid
      Count = $subkeys.Count
      SampleSerial = $first.PSChildName
      DeviceDesc = $p.DeviceDesc
      FriendlyName = $p.FriendlyName
      Service = $p.Service
      ClassGUID = $p.ClassGUID
      Driver = $p.Driver
      Mfg = $p.Mfg
    }
  }
} | Format-Table -AutoSize -Wrap

$targets = @('VID_18D1&PID_0D02','VID_18D1&PID_4E41','VID_18D1&PID_4EE1','VID_18D1&PID_4EE7','VID_1B8E&PID_C003','VID_1B8E&PID_C004','ROOT_HUB30')
foreach ($t in $targets) {
  $path = "HKLM:\SYSTEM\CurrentControlSet\Enum\USB\$t"
  if (Test-Path $path) {
    $sub = Get-ChildItem $path | Select-Object -First 3
    foreach ($s in $sub) {
      $p = Get-ItemProperty $s.PSPath
      [PSCustomObject]@{
        Key = "$t\$($s.PSChildName)"
        DeviceDesc = $p.DeviceDesc
        FriendlyName = $p.FriendlyName
        HardwareID = ($p.HardwareID -join '; ')
        CompatibleIDs = ($p.CompatibleIDs -join '; ')
        Service = $p.Service
        Class = $p.Class
        ClassGUID = $p.ClassGUID
        Driver = $p.Driver
        Mfg = $p.Mfg
        LocationInformation = $p.LocationInformation
        Capabilities = $p.Capabilities
      }
    }
  }
} | Format-List
